    # Validate inputs
    if type(seats) is not int or seats < 0:
        raise ValueError("invalid allocation")
    if not isinstance(weights, dict) or not weights:
        raise ValueError("invalid allocation")
    for name, v in weights.items():
        if type(v) is not int or v < 0:
            raise ValueError("invalid allocation")
    total = sum(weights.values())
    # Handle zero total
    if total == 0:
        if seats != 0:
            raise ValueError("zero total")
        return {k: 0 for k in weights}, {k: 0 for k in weights}
    # Compute floor allocations and remainders using integer arithmetic
    base = {}
    remainders = {}
    for name, v in weights.items():
        # floor(seats * v / total)
        alloc = (seats * v) // total
        base[name] = alloc
        # remainder = seats * v - alloc * total
        rem = seats * v - alloc * total
        remainders[name] = rem
    return base, remainders

